// TestClassifyOwnedFile: a generated file's state is decided by what sits at
// its path, never by what a link there resolves to — a link to a file holding
// the exact generated bytes is not engine-sync's file, so it is SHADOWED.
func TestClassifyOwnedFile(t *testing.T) {
	want := []byte(artifact.Marker(artifact.YAMLFront, "agents/lead.md") + "\nname: lead\n")
	for name, tc := range map[string]struct {
		plant func(t *testing.T, path string)
		state string
	}{
		"absent":                 {plant: func(*testing.T, string) {}, state: StateMissing},
		"exact bytes":            {plant: func(t *testing.T, path string) { plantFile(t, path, want) }, state: StateInstalled},
		"owned, other bytes":     {plant: func(t *testing.T, path string) { plantFile(t, path, append(want, "old\n"...)) }, state: StateStale},
		"unowned regular file":   {plant: func(t *testing.T, path string) { plantFile(t, path, []byte("mine\n")) }, state: StateShadowed},
		"link to the same bytes": {plant: func(t *testing.T, path string) { plantLink(t, path, want) }, state: StateShadowed},
		"directory":              {plant: func(t *testing.T, path string) { plantDir(t, path) }, state: StateShadowed},
	} {
		t.Run(name, func(t *testing.T) {
			path := filepath.Join(testjail.Scratch(t), "agents", "lead.md")
			plantDir(t, filepath.Dir(path))
			tc.plant(t, path)
			got, err := classifyOwnedFile(path, want)
			if err != nil || got != tc.state {
				t.Fatalf("classifyOwnedFile = %q (%v), want %q", got, err, tc.state)
			}
		})
	}
}

// TestRegistryStrays: in a managed registry, an undeclared entry engine-sync
// owns (its marker, or a link into an owned directory) is STALE, and anything
// else at an undeclared name is a STRAY warning; declared paths and other
// suffixes are not its business, and an absent registry has no strays.
func TestRegistryStrays(t *testing.T) {
	root := testjail.Scratch(t)
	registry, owned, foreign := filepath.Join(root, "agents"), filepath.Join(root, "owned"), filepath.Join(root, "foreign")
	for _, dir := range []string{registry, owned, foreign} {
		plantDir(t, dir)
	}
	plantFile(t, filepath.Join(owned, "linked.toml"), []byte("name = \"linked\"\n"))
	plantFile(t, filepath.Join(foreign, "theirs.toml"), []byte("name = \"theirs\"\n"))
	plantFile(t, filepath.Join(registry, "declared.toml"), []byte("name = \"declared\"\n"))
	plantFile(t, filepath.Join(registry, "retired.toml"), []byte(artifact.Marker(artifact.TOML, "agents/retired.md")+"\nname = \"retired\"\n"))
	plantFile(t, filepath.Join(registry, "stranger.toml"), []byte("name = \"stranger\"\n"))
	plantFile(t, filepath.Join(registry, "notes.md"), []byte("not a role\n"))
	for name, target := range map[string]string{"linked.toml": filepath.Join(owned, "linked.toml"), "theirs.toml": filepath.Join(foreign, "theirs.toml")} {
		if err := os.Symlink(target, filepath.Join(registry, name)); err != nil {
			t.Fatal(err)
		}
	}
	got, err := registryStrays(EngineCodex, registry, ".toml", map[string]bool{filepath.Join(registry, "declared.toml"): true}, []string{owned})
	if err != nil {
		t.Fatal(err)
	}
	want := map[string]string{"linked": StateStale, "retired": StateStale, "stranger": StateStray, "theirs": StateStray}
	if len(got) != len(want) {
		t.Fatalf("strays = %+v, want %v", got, want)
	}
	for _, s := range got {
		if want[s.Name] != s.State || s.Engine != EngineCodex || s.Path != filepath.Join(registry, s.Name+".toml") {
			t.Fatalf("stray %+v, want state %q", s, want[s.Name])
		}
	}
	if absent, err := registryStrays(EngineCodex, filepath.Join(root, "absent"), ".toml", nil, nil); err != nil || absent != nil {
		t.Fatalf("absent registry = %+v (%v), want none", absent, err)
	}
}

func plantFile(t *testing.T, path string, content []byte) {
	t.Helper()
	if err := os.WriteFile(path, content, 0o644); err != nil {
		t.Fatal(err)
	}
}

func plantDir(t *testing.T, path string) {
	t.Helper()
	if err := os.MkdirAll(path, 0o755); err != nil {
		t.Fatal(err)
	}
}

// plantLink plants a symlink at path to a sibling file holding content.
func plantLink(t *testing.T, path string, content []byte) {
	t.Helper()
	target := path + ".real"
	plantFile(t, target, content)
	if err := os.Symlink(target, path); err != nil {
		t.Fatal(err)
	}
}

// TestCheckSourceVariantsRelativeRoot pins the check a caller runs from the
// project directory (`engine-sync check .`): the agents directory and its
// variants.json resolve once, never joined twice.
func TestCheckSourceVariantsRelativeRoot(t *testing.T) {
	root, home := testjail.Scratch(t), testjail.Scratch(t)
	dir := filepath.Join(root, "templates", "agents")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	for name, content := range map[string]string{
		"lead.md":       "---\nname: lead\ndescription: Leads.\ntools: Read\n---\nLead.\n",
		"variants.json": `{"version":2,"variants":{"lead-pro":{"from":"lead","set":{"description":"Leads more."}}}}`,
	} {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	cfg := config.Default()
	cfg.Machine.SourceAgentsDir = "templates/agents"
	t.Chdir(root)
	problems, _ := CheckSourceVariants(".", home, cfg)
	if len(problems) != 0 {
		t.Fatalf("problems = %q, want none", problems)
	}
}

// TestCheckSourceVariantsReadsTheConfiguredDeclaration: check validates the
// declaration machine.variants names (relative to the agents directory), and
// a configured declaration that is missing is a problem, never nothing.
func TestCheckSourceVariantsReadsTheConfiguredDeclaration(t *testing.T) {
	root, home := testjail.Scratch(t), testjail.Scratch(t)
	dir := filepath.Join(root, "agents")
	plantDir(t, dir)
	plantFile(t, filepath.Join(dir, "lead.md"), []byte("---\nname: lead\ndescription: Leads.\ntools: Read\n---\nLead.\n"))
	plantFile(t, filepath.Join(dir, "custom.json"), []byte(`{"version":2,"variants":{"lead-pro":{"from":"ghost"}}}`))
	for _, tc := range []struct{ variants, want string }{
		{variants: "custom.json", want: "ghost"},
		{variants: "absent.json", want: filepath.Join(dir, "absent.json")},
	} {
		cfg := config.Default()
		cfg.Machine.SourceAgentsDir = "agents"
		cfg.Machine.Variants = tc.variants
		problems, _ := CheckSourceVariants(root, home, cfg)
		if !strings.Contains(strings.Join(problems, "\n"), tc.want) {
			t.Fatalf("%s: problems = %q, want one naming %q", tc.variants, problems, tc.want)
		}
	}
}

// TestCheckReportsEveryAgentGlobalSkips: check runs global's per-agent
// decision, so an agent only its OpenCode render refuses (a server-wide MCP
// tools entry) fails check with the message global skips it with.
func TestCheckReportsEveryAgentGlobalSkips(t *testing.T) {
	root, home := testjail.Scratch(t), testjail.Scratch(t)
	dir := filepath.Join(root, "agents")
	plantDir(t, dir)
	plantFile(t, filepath.Join(dir, "lead.md"), []byte("---\nname: lead\ndescription: Leads.\ntools: Read, mcp__github\n---\nLead.\n"))
	plantFile(t, filepath.Join(dir, "variants.json"), []byte(`{"version":2,"variants":{"lead-pro":{"from":"lead","set":{"description":"Leads more."}}}}`))
	cfg := config.Default()
	cfg.Machine.SourceAgentsDir = "agents"
	result, err := runFixtureMachineAgents(GlobalAgentsOptions{SourceRepo: root, Home: home, Config: &cfg})
	if err != nil || len(result.Problems) == 0 {
		t.Fatalf("global: problems %q (%v), want the OpenCode tools refusal", result.Problems, err)
	}
	problems, _ := CheckSourceVariants(root, home, cfg)
	joined := strings.Join(problems, "\n")
	for _, want := range result.Problems {
		if !strings.Contains(joined, want) {
			t.Fatalf("check problems = %q, want global's skip %q", problems, want)
		}
	}
}
